"""Actual two-path routing and kernel reverse-path filtering in disposable namespaces."""
import json,os,pathlib,secrets,subprocess,sys
sys.path.insert(0,str(pathlib.Path.cwd()))
import task
assert os.geteuid()==0
workers=[]
def run(*args):return subprocess.check_output(args,text=True,timeout=5)
def inside(peer,*args):return run('nsenter','-t',str(peer.pid),'-n',*args)
def rpc(peer,**data):
 peer.stdin.write(json.dumps(data)+'\n');peer.stdin.flush();line=peer.stdout.readline();assert line,'worker exited';result=json.loads(line);assert result['ok'],result;return result['result']
try:
 for _ in range(2):
  peer=subprocess.Popen(['unshare','-n','--',sys.executable,'-I','-B','checks/rpf_worker.py'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True);workers.append(peer)
  ready=json.loads(peer.stdout.readline());assert ready['ready'] and ready['pid']==peer.pid
 sender,receiver=workers
 for peer in workers:inside(peer,'ip','link','set','lo','up')
 for index in range(2):
  c='c'+str(index);r='r'+str(index)
  run('ip','link','add',c,'type','veth','peer','name',r);run('ip','link','set',c,'netns',str(sender.pid));run('ip','link','set',r,'netns',str(receiver.pid))
  for peer,name,host in [(sender,c,1),(receiver,r,2)]:
   inside(peer,'ip','link','set',name,'up');inside(peer,'ip','addr','add',f'10.0.{index+1}.{host}/24','dev',name)
 for name,value in [('all',0),('r0',1),('r1',1)]:inside(receiver,'sysctl','-qw',f'net.ipv4.conf.{name}.rp_filter={value}')
 rpc(receiver,op='listen',interface='r0')
 def packet(source='10.0.1.1',spoof=False):
  payload=secrets.token_bytes(32).hex();rpc(sender,op='spoof' if spoof else 'send',source=source,destination='10.0.1.2',payload=payload)
  return rpc(receiver,op='observed',payload=payload)
 assert packet()=={'nic':True,'application':True},'healthy symmetric baseline'
 inside(receiver,'ip','route','add','10.0.1.1/32','via','10.0.2.1','dev','r1')
 assert json.loads(inside(receiver,'ip','-j','route','get','10.0.1.1'))[0]['dev']=='r1'
 assert packet()=={'nic':True,'application':False},'strict reverse path must drop actual NIC-arriving UDP'
 before_routes=json.loads(inside(receiver,'ip','-j','route','show','table','all'))
 print('NATIVE_LINUX_READY',flush=True)
 print('STUDENT_OPERATION_ENTERED: actual UDP observed at receiver NIC but kernel strict reverse-path check prevents application delivery after reverse route changed',flush=True)
 task.repair(receiver.pid,'r0')
 assert packet()=={'nic':True,'application':True},'valid asymmetric traffic must be delivered'
 assert packet('198.18.0.5',True)=={'nic':True,'application':False},'unroutable spoofed source must still be dropped by kernel'
 assert json.loads(inside(receiver,'ip','-j','route','show','table','all'))==before_routes,'preserve approved asymmetric route and all routing policy'
 for name,value in [('all','0'),('r0','2'),('r1','1')]:assert inside(receiver,'sysctl','-n',f'net.ipv4.conf.{name}.rp_filter').strip()==value
 task.repair(receiver.pid,'r0');assert packet()=={'nic':True,'application':True}
 print('NATIVE_RPF_ASYMMETRIC_ROUTE_NIC_ARRIVAL_APP_DROP_REPRODUCED_INTERFACE_ONLY_LOOSE_MODE_RESTORES_VALID_UDP_UNROUTABLE_SPOOF_STILL_DROPPED_ROUTES_AND_OTHER_INTERFACE_STRICT_PRESERVED',flush=True)
 print('NATIVE_SEMANTIC_ASSERTIONS_PASSED',flush=True)
finally:
 for peer in reversed(workers):
  if peer.poll() is None:peer.terminate()
  try:peer.wait(timeout=4)
  except subprocess.TimeoutExpired:peer.kill();peer.wait()

