"""Trusted namespace-local UDP application and packet observer, independent of submitted repair."""
import json,os,socket,struct,sys,threading,time
received=[];captured=[];sockets=[]

def listen(sock):
 while True:
  try: payload,address=sock.recvfrom(65535);received.append(payload.hex())
  except OSError:return

def capture(sock):
 while True:
  try:
   frame=sock.recv(65535)
   if len(frame)>=42 and frame[12:14]==b'\x08\x00' and frame[23]==17:
    offset=14+(frame[14]&15)*4
    if struct.unpack('!H',frame[offset+2:offset+4])[0]==19000:captured.append(frame[offset+8:].hex())
  except OSError:return

print(json.dumps({'ready':True,'pid':os.getpid()}),flush=True)
try:
 for line in sys.stdin:
  try:
   data=json.loads(line);op=data['op']
   if op=='listen':
    udp=socket.socket(socket.AF_INET,socket.SOCK_DGRAM);udp.bind(('0.0.0.0',19000));sockets.append(udp)
    link=socket.socket(socket.AF_PACKET,socket.SOCK_RAW,socket.htons(0x0800));link.bind((data['interface'],0));sockets.append(link)
    threading.Thread(target=listen,args=(udp,),daemon=True).start();threading.Thread(target=capture,args=(link,),daemon=True).start();result=True
   elif op=='send':
    with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as udp:
     udp.bind((data['source'],0));udp.sendto(bytes.fromhex(data['payload']),(data['destination'],19000))
    result=True
   elif op=='spoof':
    payload=bytes.fromhex(data['payload']);length=20+8+len(payload)
    header=struct.pack('!BBHHHBBH4s4s',0x45,0,length,1234,0,64,17,0,socket.inet_aton(data['source']),socket.inet_aton(data['destination']))
    value=sum(struct.unpack('!10H',header));value=(value&65535)+(value>>16);value=(value&65535)+(value>>16)
    header=header[:10]+struct.pack('!H',(~value)&65535)+header[12:]
    with socket.socket(socket.AF_INET,socket.SOCK_RAW,socket.IPPROTO_RAW) as raw:raw.sendto(header+struct.pack('!HHHH',24000,19000,8+len(payload),0)+payload,(data['destination'],0))
    result=True
   elif op=='observed':
    deadline=time.monotonic()+data.get('wait',1)
    while time.monotonic()<deadline and data['payload'] not in captured:time.sleep(.01)
    time.sleep(.08);result={'nic':data['payload'] in captured,'application':data['payload'] in received}
   else:raise ValueError('unsupported trusted operation')
   print(json.dumps({'ok':True,'result':result}),flush=True)
  except Exception as exc:print(json.dumps({'ok':False,'error':type(exc).__name__+': '+str(exc)}),flush=True)
finally:
 for sock in sockets:sock.close()
